import{_ as a,o as r,c as s,j as t,a as d,a6 as o}from"./chunks/framework.BxGSG9WI.js";const m=JSON.parse('{"title":"Error Messages & Fixes","description":"Every message of the TaxJar Integration in one place: setup, saving a document, addresses, sync errors, credit notes, customers, access and the upgrade.","frontmatter":{"title":"Error Messages & Fixes","description":"Every message of the TaxJar Integration in one place: setup, saving a document, addresses, sync errors, credit notes, customers, access and the upgrade.","type":"reference","pageClass":"messages-page"},"headers":[],"relativePath":"troubleshoot/messages-and-errors.md","filePath":"troubleshoot/messages-and-errors.md"}'),n={name:"troubleshoot/messages-and-errors.md"};function i(h,e,c,l,u,g){return r(),s("div",null,[...e[0]||(e[0]=[t("h1",{id:"messages-errors",tabindex:"-1"},[d("Messages & Errors "),t("a",{class:"header-anchor",href:"#messages-errors","aria-label":'Permalink to "Messages & Errors"'},"​")],-1),t("p",null,"Each section lists the messages of one place in the app, with the cause and the fix.",-1),t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},[t("span",{class:"tip-icon",role:"img","aria-label":"Tip"})]),t("p",null,"Find a message with the search (Ctrl+K or ⌘K). Text in braces, for example {company}, is a name that changes.")],-1),o('<h2 id="setup-messages" tabindex="-1">Setup Messages <a class="header-anchor" href="#setup-messages" aria-label="Permalink to &quot;Setup Messages&quot;">​</a></h2><p>These show in TaxJar Setup and on the TaxJar Settings form.</p><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Invalid token (401). Check you copied the Live token.</td><td>The token is wrong, or it is for the other mode.</td><td>Copy the token again from TaxJar, for the correct mode. Click <strong>Connect</strong>.</td></tr><tr><td>Could not reach TaxJar. Check your connection and try again.</td><td>The server cannot reach TaxJar.</td><td>Check the internet connection of the server, then click <strong>Retry</strong>.</td></tr><tr><td>Please validate API Key for {company}.</td><td>The company is not connected.</td><td>Click <strong>Connect</strong> for that company before you continue.</td></tr><tr><td>Invalid address as per TaxJar.</td><td>TaxJar cannot find the company address.</td><td>Correct the address, then check it again.</td></tr><tr><td>At least one Live Token is required in API Credentials for Live mode.</td><td>Live mode is on, but no company has a Live token.</td><td>Add a Live token. The Sandbox message is the same for Sandbox mode.</td></tr></tbody></table><h2 id="save-messages" tabindex="-1">Save Messages <a class="header-anchor" href="#save-messages" aria-label="Permalink to &quot;Save Messages&quot;">​</a></h2><p>These show on a quotation, a sales order or a sales invoice.</p><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Customer address is not set, hence taxes are not calculated.</td><td>The document has no address.</td><td>Click <strong>Create Address →</strong>, or select an address.</td></tr><tr><td>Nexus not configured for {state}, hence no taxes are charged.</td><td>You have no nexus in the ship-to state.</td><td>If you must collect tax there, add the state in TaxJar, then <a href="/usa/sales-tax/pr-preview/pr-31/setting-up/updating-your-nexus#on-demand-nexus-sync">sync the nexus</a>.</td></tr><tr><td>Sales taxes are not applicable on export transactions.</td><td>The ship-to country is not the United States.</td><td>Nothing.</td></tr><tr><td>Company Address Required: Please set a default address for the company {company}.</td><td>The company has no address.</td><td>Add a company address in <a href="/usa/sales-tax/pr-preview/pr-31/setting-up/guided-setup#address">TaxJar Setup</a>.</td></tr><tr><td>Exchange Rate Not Found: Could not find exchange rate from {currency} to USD for {date}.</td><td>The document is not in USD, and ERPNext has no rate.</td><td>Add a <strong>Currency Exchange</strong> record to USD, or set up <strong>Currency Exchange Settings</strong>.</td></tr><tr><td>TaxJar API is unreachable. Tax has not been calculated for this document.</td><td>TaxJar did not answer. The document saved without new tax.</td><td>Wait, then save again.</td></tr><tr><td>TaxJar Tax Calculation Failed</td><td>TaxJar did not accept the data.</td><td>Read the message. If it names an address, correct that address.</td></tr><tr><td>Address Required: No Shipping Address or Billing Address is set on this transaction.</td><td>The document has no address.</td><td>Add an address to the customer, and select it on the document.</td></tr><tr><td>No Addresses Found</td><td>The customer has no address.</td><td>Add a shipping address to the customer.</td></tr><tr><td>Destination Required to File</td><td>You submit an invoice with no address, for a company that syncs.</td><td>Set a <strong>Shipping Address</strong> or a <strong>Billing Address</strong>, then submit.</td></tr></tbody></table><h2 id="address-messages" tabindex="-1">Address Messages <a class="header-anchor" href="#address-messages" aria-label="Permalink to &quot;Address Messages&quot;">​</a></h2><p>These show when you save an address.</p><table tabindex="0"><thead><tr><th>Message</th><th>Fix</th></tr></thead><tbody><tr><td>State Required</td><td>Fill in <strong>State/Province</strong>.</td></tr><tr><td>State Code Required</td><td>Fill in <strong>State Code (US)</strong>.</td></tr><tr><td>Postal Code Required</td><td>Fill in <strong>Postal Code</strong>.</td></tr><tr><td>Company Address Required: {address} is the only address {company} has…</td><td>Add another address for the company before you delete or disable this one.</td></tr></tbody></table><h2 id="sync-errors" tabindex="-1">Sync Errors <a class="header-anchor" href="#sync-errors" aria-label="Permalink to &quot;Sync Errors&quot;">​</a></h2><p>These show as the <strong>Sync Error</strong> of an invoice or a credit note. An error that ends with &quot;Automatic retry is scheduled.&quot; is temporary. The app tries again every 15 minutes, up to five times.</p><table tabindex="0"><thead><tr><th>Error</th><th>Fix</th></tr></thead><tbody><tr><td>TaxJar API Token is invalid, go to guided setup to configure.</td><td>Enter a correct token in <a href="/usa/sales-tax/pr-preview/pr-31/setting-up/guided-setup#connect">TaxJar Setup</a>, then resync.</td></tr><tr><td>{company} has no {mode} API token, and TaxJar is in {mode} mode. Enter one in the guided setup.</td><td>Enter the token for the current mode. The app then sends the invoice again within 15 minutes.</td></tr><tr><td>TaxJar is not configured for {company}. Add its API credential in the guided setup.</td><td>Connect the company in TaxJar Setup.</td></tr><tr><td>Transaction ID already exists in TaxJar, please cancel &amp; create a new transaction.</td><td>Cancel the invoice, amend it, and submit the new invoice.</td></tr><tr><td>Exempt transactions cannot have sales tax, please clear exemption or remove sales tax.</td><td>Clear the exemption, or remove the sales tax row.</td></tr><tr><td>Transaction not found in TaxJar, can&#39;t update the latest changes.</td><td>The transaction is not in TaxJar. Check the <a href="/usa/sales-tax/pr-preview/pr-31/troubleshoot/api-log">API Log</a>.</td></tr><tr><td>TaxJar could not process the request: {detail}.</td><td>Read the detail. The <a href="/usa/sales-tax/pr-preview/pr-31/troubleshoot/api-log">API Log</a> shows the request that TaxJar refused.</td></tr><tr><td>TaxJar rejected the request as malformed: {detail}.</td><td>Read the detail, and correct the field that it names.</td></tr><tr><td>This TaxJar account is not allowed to make that request</td><td>Make sure that your TaxJar plan includes the API.</td></tr><tr><td>TaxJar&#39;s API rate limit was reached</td><td>Nothing. The app tries again.</td></tr><tr><td>TaxJar is unreachable - the request timed out or the connection failed.</td><td>Nothing. The app tries again.</td></tr><tr><td>TaxJar is temporarily unreachable, TaxJar is temporarily offline for maintenance, TaxJar took too long to respond, or TaxJar hit an internal server error</td><td>Nothing. The app tries again.</td></tr><tr><td>TaxJar returned a response that could not be read…</td><td>Nothing. It is usually a short outage at TaxJar. The app tries again.</td></tr><tr><td>No TaxJar payload could be built for this document - check the company&#39;s TaxJar configuration.</td><td>Check the company in TaxJar Setup. The app tries again.</td></tr></tbody></table><h3 id="sync-button-messages" tabindex="-1">Sync Button Messages <a class="header-anchor" href="#sync-button-messages" aria-label="Permalink to &quot;Sync Button Messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Fix</th></tr></thead><tbody><tr><td>Invoice Not Submitted</td><td>Submit the invoice first.</td></tr><tr><td>Check Before You Sync</td><td>The invoice is from version 15. Run the <a href="/usa/sales-tax/pr-preview/pr-31/reference/upgrade-from-version-15#check-older-invoices">upgrade check</a> first.</td></tr><tr><td>Filing Is Off</td><td>Turn on <strong>Sync Transactions to TaxJar</strong> for the company.</td></tr><tr><td>TaxJar Sync Failed</td><td>Read the message below the title.</td></tr></tbody></table><h2 id="credit-note-messages" tabindex="-1">Credit Note Messages <a class="header-anchor" href="#credit-note-messages" aria-label="Permalink to &quot;Credit Note Messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Fix</th></tr></thead><tbody><tr><td>Original Invoice Not Synced</td><td>Send the original invoice to TaxJar, then submit the credit note.</td></tr><tr><td>TaxJar: Missing Return Reference</td><td>Make the credit note from the original invoice: <strong>Create</strong> → <strong>Return / Credit Note</strong>.</td></tr><tr><td>{customer} has no submitted invoice.</td><td>Submit an invoice for the customer, then make the credit note.</td></tr><tr><td>Please select a Sales Invoice</td><td>Select the original invoice in the dialog.</td></tr></tbody></table><h2 id="customer-messages" tabindex="-1">Customer Messages <a class="header-anchor" href="#customer-messages" aria-label="Permalink to &quot;Customer Messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Fix</th></tr></thead><tbody><tr><td>Nothing to Sync To</td><td>No company uses TaxJar. Check the companies in TaxJar Setup.</td></tr><tr><td>Company Not Allowed</td><td>The company does not use TaxJar. Check the companies in TaxJar Setup.</td></tr><tr><td>Customer Not Deleted</td><td>TaxJar could not remove the customer. Wait, then delete the customer again.</td></tr><tr><td>Not Sent</td><td>The customer waited too long in the queue. Select the row and click <strong>Resync with TaxJar</strong>.</td></tr><tr><td>Exempt Region Required</td><td>Select at least one exempt region, or click <strong>Select All</strong>.</td></tr><tr><td>…exemption details were saved but not sent to TaxJar.</td><td>TaxJar is off, or no company uses TaxJar. Fix the cause, then send the customer again.</td></tr></tbody></table><h2 id="access-messages" tabindex="-1">Access Messages <a class="header-anchor" href="#access-messages" aria-label="Permalink to &quot;Access Messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Fix</th></tr></thead><tbody><tr><td>You do not have {right} access to {document type}, ask your administrator to update permissions for your user.</td><td>Ask an administrator to give the role for the task. Refer to <a href="/usa/sales-tax/pr-preview/pr-31/setting-up/roles-and-permissions#permissions-by-task">Permissions by Task</a>.</td></tr><tr><td>A TaxJar Manager can fetch them from TaxJar.</td><td>Only a TaxJar Manager can update the nexus or the categories.</td></tr></tbody></table><h2 id="upgrade-messages" tabindex="-1">Upgrade Messages <a class="header-anchor" href="#upgrade-messages" aria-label="Permalink to &quot;Upgrade Messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Fix</th></tr></thead><tbody><tr><td>Live Mode Required</td><td>Change <strong>API Mode</strong> to <strong>Live</strong> in TaxJar Setup, then run the check.</td></tr><tr><td>Nothing to Check</td><td>No version 15 invoice waits for the check. Nothing to do.</td></tr><tr><td>A TaxJar Manager can run the check.</td><td>Ask a TaxJar Manager to run the check.</td></tr></tbody></table>',22)])])}const x=a(n,[["render",i]]);export{m as __pageData,x as default};
